// libRoot is the library root_path the scan flows into the ScanRequest.
const libRoot = "/library/tv"

// setupStore opens a temp SQLite store, seeds the built-in TV module, and
// creates one library bound to it. The returned libraryID is the one Run scans.
func setupStore(t *testing.T) (*store.Store, *module.Registry, int64) {
	t.Helper()
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "scan.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	r, err := module.Open(ctx, s)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	libID, err := s.CreateLibrary(ctx, "tv", libRoot, "TV Series")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	return s, r, libID
}

// fakeScanner is the second real implementation of sdk.Scanner (R8): an
// in-process emitter of canned DiscoveredFiles + IdentifyResults. It is how the
// orchestrator is exercised without a subprocess (the real subprocess client is
// exercised by the T11 integration test). blockAfter>0 emits that many files
// then blocks until ctx is done, so a mid-stream cancel is testable.
type fakeScanner struct {
	files      []*scannerv1.DiscoveredFile
	identify   map[string]*scannerv1.IdentifyResult
	identifyEr error
	blockAfter int
	gotReq     *scannerv1.ScanRequest
}

func (f *fakeScanner) Scan(ctx context.Context, req *scannerv1.ScanRequest) (<-chan *scannerv1.DiscoveredFile, error) {
	f.gotReq = req
	ch := make(chan *scannerv1.DiscoveredFile, len(f.files)+1)
	go func() {
		sent := 0
		for _, fl := range f.files {
			select {
			case ch <- fl:
			case <-ctx.Done():
				close(ch)
				return
			}
			sent++
			if f.blockAfter > 0 && sent == f.blockAfter {
				<-ctx.Done() // block: simulates a scanner mid-stream when the consumer cancels
				close(ch)
				return
			}
		}
		close(ch)
	}()
	return ch, nil
}

func (f *fakeScanner) Identify(_ context.Context, req *scannerv1.IdentifyRequest) (*scannerv1.IdentifyResult, error) {
	if f.identifyEr != nil {
		return nil, f.identifyEr
	}
	fid := req.GetFile().GetFileId()
	if r, ok := f.identify[fid]; ok {
		return r, nil
	}
	return &scannerv1.IdentifyResult{FileId: fid, MediaType: req.GetModuleType()}, nil
}

// recordingResolver wraps a scanner and records the (pluginID, capabilityID) it
// was resolved with, so the test can assert the module's binding reached the
// resolver (S2). It satisfies the unexported scannerResolver seam.
type recordingResolver struct {
	scanner      sdk.Scanner
	pluginID     string
	capabilityID string
	called       bool
}

func (r *recordingResolver) resolve(pluginID, capabilityID string) (sdk.Scanner, error) {
	r.pluginID, r.capabilityID, r.called = pluginID, capabilityID, true
	return r.scanner, nil
}

// passthroughEnricher returns the base document unchanged with status "new" —
// the scan-orchestration tests exercise the scan drain/assemble/put flow in
// isolation. Post-B1 it is the retained serial seam (B6): runScan still accepts
// an enricher so the serial path stays wired, but persist no longer invokes it
// (TestRunScan_AsyncEnqueue asserts non-invocation).
func passthroughEnricher() enricher {
	return func(_ context.Context, _ module.Module, doc map[string]any, _ *scannerv1.IdentifyResult) (map[string]any, string, enrich.Result, error) {
		return doc, "new", enrich.Result{}, nil
	}
}

// forbiddingEnricher counts inline invocations of the serial seam. Post-B1 scan
// MUST NOT drive enrichment inline (B1/AC-async): a non-zero count fails the
// test. The returned status is irrelevant (persist ignores the enricher now).
func forbiddingEnricher(called *int) enricher {
	return func(context.Context, module.Module, map[string]any, *scannerv1.IdentifyResult) (map[string]any, string, enrich.Result, error) {
		*called++
		return nil, "", enrich.Result{}, nil
	}
}

// recordingNotifier is the fake Notify seam (S5): it records the libraryID of
// each call and, via the store, how many items were already persisted AT CALL
// TIME — so a test can assert Notify fires post-drain (all items persisted),
// not mid-stream. Mutex-guarded so it is safe under -race.
type recordingNotifier struct {
	mu      sync.Mutex
	calls   []int64
	atCount []int // items persisted at each call
	store   *store.Store
}

func (n *recordingNotifier) notify(_ context.Context, libraryID int64) {
	n.mu.Lock()
	defer n.mu.Unlock()
	items, _ := n.store.QueryItems(context.Background(), libraryID, "", 10000, 0)
	n.calls = append(n.calls, libraryID)
	n.atCount = append(n.atCount, len(items))
}

func (n *recordingNotifier) count() int {
	n.mu.Lock()
	defer n.mu.Unlock()
	return len(n.calls)
}

// snapshot returns defensive copies of the recorded calls + per-call persisted
// counts, so a test can assert post-drain ordering without racing a later call.
func (n *recordingNotifier) snapshot() (calls []int64, atCount []int) {
	n.mu.Lock()
	defer n.mu.Unlock()
	calls = append(calls, n.calls...)
	atCount = append(atCount, n.atCount...)
	return calls, atCount
}

func mkFile(fileID, rel string, ffprobe []byte, warnings []string) *scannerv1.DiscoveredFile {
	return &scannerv1.DiscoveredFile{
		FileId:       fileID,
		RelativePath: rel,
		FfprobeJson:  ffprobe,
		Warnings:     warnings,
	}
}

// mkIdentified builds an IdentifyResult whose parsed Struct carries parsedJSON
// (a JSON object) without this test importing structpb: the JSON is unmarshaled
// into the message so the generated structpb.UnmarshalJSON builds the Struct.
func mkIdentified(fileID, parsedJSON string) *scannerv1.IdentifyResult {
	r := &scannerv1.IdentifyResult{FileId: fileID, MediaType: "tv"}
	if parsedJSON != "" {
		if err := json.Unmarshal([]byte(`{"parsed":`+parsedJSON+`,"media_type":"tv"}`), r); err != nil {
			panic(fmt.Sprintf("mkIdentified %q: %v", parsedJSON, err))
		}
	}
	return r
}

// scannedDoc is a typed view of the assembled §3.1 document for assertions.
type scannedDoc struct {
	FileID        string         `json:"file_id"`
	ModuleType    string         `json:"module_type"`
	SchemaVersion int            `json:"schema_version"`
	Parsed        map[string]any `json:"parsed"`
	Ffprobe       map[string]any `json:"ffprobe"`
}

func decodeDoc(t *testing.T, raw json.RawMessage) scannedDoc {
	t.Helper()
	var d scannedDoc
	if err := json.Unmarshal(raw, &d); err != nil {
		t.Fatalf("decode document: %v (raw=%s)", err, string(raw))
	}
	return d
}

// TestRun_HardFailResolution covers Run's exported entrypoint with REAL store +
// module + an empty plugin.Manager: the library/module/scanner resolution hard
// failures (B1). The happy path needs a fake scanner, which the concrete
// *plugin.Manager cannot carry from this package, so it is covered by
// TestRunScan_Orchestration via the runScan seam and end-to-end by T11.
func TestRun_HardFailResolution(t *testing.T) {
	s, r, libID := setupStore(t)
	deps := Deps{Store: s, Plugins: plugin.Open(plugin.Deps{}), Modules: r}

	for _, tc := range []struct {
		name string
		id   int64
	}{
		{"library_not_found", libID + 9999},
		{"scanner_not_resolvable", libID}, // no plugin loaded -> Scanner() errors
	} {
		t.Run(tc.name, func(t *testing.T) {
			res, err := Run(context.Background(), deps, tc.id)
			if err == nil {
				t.Fatalf("Run: want error, got nil (res=%+v)", res)
			}
			if res.Persisted != 0 {
				t.Errorf("Persisted = %d, want 0 on hard failure", res.Persisted)
			}
			if res.LibraryID != tc.id {
				t.Errorf("LibraryID = %d, want %d", res.LibraryID, tc.id)
			}
		})
	}
}

// TestRunScan_Orchestration is the joint test for seams S2+S3+S4 (one test):
// it injects a fake sdk.Scanner via the resolver seam and asserts Run resolves
// the module/binding, drains the stream, assembles the §3.1 document, and
// PutItems each file (AC-1); an unprobeable file is still persisted with empty
// ffprobe + a warning (AC-6); identify failures soft-fail (AC-6).
func TestRunScan_Orchestration(t *testing.T) {
	probed := []byte(`{"format":{"filename":"s01e01.mkv","duration":"120.5"},"streams":[{"codec_type":"video"}]}`)

	type expect struct {
		discovered  int
		persisted   int
		wantErr     bool
		minWarnings int
		check       func(t *testing.T, items []store.Item)
	}

	cases := []struct {
		name     string
		scanner  *fakeScanner
		resolve  scannerResolver
		expected expect
	}{
		{
			// AC-1: items persisted match the scanner emission + correct Document
			// shape. AC-6: the unprobeable file is still persisted with empty
			// ffprobe + a warning.
			name: "persist_probed_and_unprobeable",
			scanner: &fakeScanner{
				files: []*scannerv1.DiscoveredFile{
					mkFile("f1", "Show/S01E01.mkv", probed, nil),
					mkFile("f2", "Show/S01E02.mkv", nil, []string{"ffprobe timed out"}),
				},
				identify: map[string]*scannerv1.IdentifyResult{
					"f1": mkIdentified("f1", `{"title":"Breaking Bad","season":1,"episode":1,"release_group":"AVC"}`),
					"f2": mkIdentified("f2", `{"title":"Breaking Bad","season":1,"episode":2,"release_group":"AVC"}`),
				},
			},
			expected: expect{
				discovered:  2,
				persisted:   2,
				minWarnings: 1, // the ffprobe warning from f2
				check: func(t *testing.T, items []store.Item) {
					byFile := map[string]store.Item{}
					for _, it := range items {
						byFile[it.FileID] = it
					}
					if len(byFile) != 2 {
						t.Fatalf("persisted items = %d, want 2", len(byFile))
					}
					d1 := decodeDoc(t, byFile["f1"].Document)
					if d1.ModuleType != "tv" {
						t.Errorf("f1 module_type = %q, want tv", d1.ModuleType)
					}
					if d1.SchemaVersion != 1 {
						t.Errorf("f1 schema_version = %d, want 1", d1.SchemaVersion)
					}
					if d1.FileID != "f1" {
						t.Errorf("f1 file_id = %q, want f1", d1.FileID)
					}
					if d1.Ffprobe == nil {
						t.Errorf("f1 ffprobe = nil, want the verbatim ffprobe object")
					} else if fn, _ := d1.Ffprobe["format"].(map[string]any); fn == nil || fn["filename"] != "s01e01.mkv" {
						t.Errorf("f1 ffprobe.format.filename = %v, want s01e01.mkv (verbatim)", d1.Ffprobe["format"])
					}
					if d1.Parsed["title"] != "Breaking Bad" {
						t.Errorf("f1 parsed.title = %v, want Breaking Bad", d1.Parsed["title"])
					}
					if d1.Parsed["release_group"] != "AVC" {
						t.Errorf("f1 parsed.release_group = %v, want AVC", d1.Parsed["release_group"])
					}
					// AC-6: unprobeable file still persisted, empty ffprobe, parsed intact.
					d2 := decodeDoc(t, byFile["f2"].Document)
					if d2.Ffprobe != nil {
						t.Errorf("f2 ffprobe = %v, want nil (unprobeable)", d2.Ffprobe)
					}
					if d2.Parsed["title"] != "Breaking Bad" {
						t.Errorf("f2 parsed.title = %v, want Breaking Bad", d2.Parsed["title"])
					}
				},
			},
		},
		{
			// AC-6 philosophy: an Identify failure is a soft warning; the scan
			// continues and never hard-fails (ctx is not cancelled here).
			name: "identify_error_soft_fail",
			scanner: &fakeScanner{
				files: []*scannerv1.DiscoveredFile{
					mkFile("f1", "Show/S01E01.mkv", probed, nil),
					mkFile("f2", "Show/S01E02.mkv", nil, nil),
				},
				identifyEr: errors.New("parser blew up"),
			},
			expected: expect{
				discovered:  2,
				persisted:   0,
				minWarnings: 2, // one per file
			},
		},
		{
			name:    "empty_stream",
			scanner: &fakeScanner{files: nil, identify: map[string]*scannerv1.IdentifyResult{}},
			expected: expect{
				discovered: 0,
				persisted:  0,
			},
		},
		{
			// B1 hard-fail: the scanner capability cannot be resolved.
			name:    "resolver_error_hard_fail",
			scanner: &fakeScanner{},
			resolve: func(_, _ string) (sdk.Scanner, error) { return nil, errors.New("capability unavailable") },
			expected: expect{
				discovered: 0,
				persisted:  0,
				wantErr:    true,
			},
		},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			s, r, libID := setupStore(t)
			rr := &recordingResolver{scanner: tc.scanner}
			resolve := tc.resolve
			if resolve == nil {
				resolve = rr.resolve
			}

			res, err := runScan(context.Background(), s, r, resolve, passthroughEnricher(), nil, libID)
			if tc.expected.wantErr && err == nil {
				t.Fatalf("runScan: want error, got nil (res=%+v)", res)
			}
			if !tc.expected.wantErr && err != nil {
				t.Fatalf("runScan: want nil error, got %v", err)
			}
			if res.Discovered != tc.expected.discovered {
				t.Errorf("Discovered = %d, want %d", res.Discovered, tc.expected.discovered)
			}
			if res.Persisted != tc.expected.persisted {
				t.Errorf("Persisted = %d, want %d", res.Persisted, tc.expected.persisted)
			}
			if len(res.Warnings) < tc.expected.minWarnings {
				t.Errorf("len(Warnings) = %d, want >= %d (%v)", len(res.Warnings), tc.expected.minWarnings, res.Warnings)
			}
			if res.StartedAt.IsZero() || res.FinishedAt.IsZero() {
				t.Errorf("timestamps not set: started=%v finished=%v", res.StartedAt, res.FinishedAt)
			}
			if !res.FinishedAt.After(res.StartedAt) && !res.FinishedAt.Equal(res.StartedAt) {
				t.Errorf("FinishedAt (%v) before StartedAt (%v)", res.FinishedAt, res.StartedAt)
			}

			// S2: the module's TV binding reached the resolver for every
			// non-resolver-error case, and the scanner saw module_type=tv +
			// the library root (no media_type branching in the orchestrator).
			if tc.name != "resolver_error_hard_fail" {
				if !rr.called || rr.pluginID != "base-scanner" || rr.capabilityID != "default" {
					t.Errorf("resolver called=%v binding=(%q,%q), want (base-scanner,default)",
						rr.called, rr.pluginID, rr.capabilityID)
				}
				if tc.scanner.gotReq == nil {
					t.Fatalf("scanner.Scan was not called")
				}
				if tc.scanner.gotReq.ModuleType != "tv" {
					t.Errorf("ScanRequest.ModuleType = %q, want tv (opaque from module config)", tc.scanner.gotReq.ModuleType)
				}
				if tc.scanner.gotReq.LibraryPath != libRoot {
					t.Errorf("ScanRequest.LibraryPath = %q, want %q", tc.scanner.gotReq.LibraryPath, libRoot)
				}
			}

			if tc.expected.check != nil {
				items, qerr := s.QueryItems(context.Background(), libID, "", 100, 0)
				if qerr != nil {
					t.Fatalf("QueryItems: %v", qerr)
				}
				tc.expected.check(t, items)
			}

			// AC-6 detail: the unprobeable case must surface its ffprobe warning.
			if tc.name == "persist_probed_and_unprobeable" {
				found := false
				for _, w := range res.Warnings {
					if strings.Contains(w, "ffprobe timed out") {
						found = true
					}
				}
				if !found {
					t.Errorf("warnings %v do not contain the scanner's ffprobe warning", res.Warnings)
				}
			}
		})
	}
}

// TestRunScan_OptionsForwarded asserts the module config's scanner options
// reach the ScanRequest.Options well-known Struct verbatim (B2), proving the
// structpb-free wrapper-unmarshal preserves the module config payload.
func TestRunScan_OptionsForwarded(t *testing.T) {
	s, r, libID := setupStore(t)
	sc := &fakeScanner{
		files:    []*scannerv1.DiscoveredFile{mkFile("f1", "a.mkv", nil, nil)},
		identify: map[string]*scannerv1.IdentifyResult{"f1": mkIdentified("f1", `{"title":"X"}`)},
	}
	rr := &recordingResolver{scanner: sc}
	if _, err := runScan(context.Background(), s, r, rr.resolve, passthroughEnricher(), nil, libID); err != nil {
		t.Fatalf("runScan: %v", err)
	}
	if sc.gotReq == nil || sc.gotReq.Options == nil {
		t.Fatalf("ScanRequest.Options = nil, want the module config options (filename_format, exclude_patterns, ...)")
	}
	// Round-trip the populated *structpb.Struct back to JSON via its marshaler.
	optsBytes, err := json.Marshal(sc.gotReq.Options)
	if err != nil {
		t.Fatalf("marshal options: %v", err)
	}
	var opts map[string]any
	if err := json.Unmarshal(optsBytes, &opts); err != nil {
		t.Fatalf("decode options: %v", err)
	}
	if opts["filename_format"] != "SxxExx" {
		t.Errorf("options.filename_format = %v, want SxxExx", opts["filename_format"])
	}
	if opts["follow_symlinks"] != false {
		t.Errorf("options.follow_symlinks = %v, want false", opts["follow_symlinks"])
	}
	excl, _ := opts["exclude_patterns"].([]any)
	if len(excl) != 3 { // the seeded TV config excludes *.nfo, *.jpg, *.srt
		t.Errorf("options.exclude_patterns len = %d, want 3 (got %v)", len(excl), opts["exclude_patterns"])
	}
}

// TestRunScan_ContextCancellation (B6): cancelling the context mid-stream
// aborts the drain cleanly, the partial item already PutItem-ed remains, and
// Run returns a context error. The fake emits one file then blocks so the cancel
// lands while runScan is waiting for the next file.
func TestRunScan_ContextCancellation(t *testing.T) {
	s, r, libID := setupStore(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sc := &fakeScanner{
		files: []*scannerv1.DiscoveredFile{
			mkFile("f1", "a.mkv", []byte(`{"format":{"duration":"10"}}`), nil),
			mkFile("f2", "b.mkv", nil, nil),
		},
		identify: map[string]*scannerv1.IdentifyResult{
			"f1": mkIdentified("f1", `{"title":"A"}`),
			"f2": mkIdentified("f2", `{"title":"B"}`),
		},
		blockAfter: 1, // emit f1, then block until ctx is cancelled
	}
	rr := &recordingResolver{scanner: sc}
	notify := &recordingNotifier{store: s}

	done := make(chan error, 1)
	go func() {
		_, err := runScan(ctx, s, r, rr.resolve, passthroughEnricher(), notify.notify, libID)
		done <- err
	}()

	// Wait until f1 is persisted (partial progress survives the cancel), then
	// cancel mid-stream. Poll with a background ctx so the cancel doesn't fail
	// the polling query.
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		if items, _ := s.QueryItems(context.Background(), libID, "", 100, 0); len(items) >= 1 {
			break
		}
		time.Sleep(2 * time.Millisecond)
	}
	cancel()

	select {
	case err := <-done:
		if err == nil {
			t.Fatal("runScan: want context error, got nil")
		}
	case <-time.After(3 * time.Second):
		t.Fatal("runScan did not return after cancel (goroutine leak?)")
	}

	// B6: the partial item remains; idempotent re-scan will resume. f2 never ran.
	items, err := s.QueryItems(context.Background(), libID, "", 100, 0)
	if err != nil {
		t.Fatalf("QueryItems: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("persisted items = %d, want exactly 1 (the file emitted before cancel)", len(items))
	}
	if items[0].FileID != "f1" {
		t.Errorf("persisted FileID = %q, want f1", items[0].FileID)
	}
	// B7: a cancelled drain did NOT complete, so Notify is NOT called (no
	// half-drained handoff to the queue).
	if n := notify.count(); n != 0 {
		t.Errorf("Notify called %d times on cancelled drain, want 0", n)
	}
}

// TestRunScan_AsyncEnqueue is the joint test for seam S5 (scan→Notify) and the
// B1 serial→async migration: it injects a forbidding enricher (must NOT be
// invoked — inline enrich is gone) + a recording notifier, and asserts scan
// persists items "pending" with the base document (parsed present for the
// worker's reconstruction, D-Q2/S7), then hands the library to the queue via
// Notify exactly once AFTER the drain completes. The async drain itself is the
// queue's job (covered by queue_test.go + the T08 golden).
func TestRunScan_AsyncEnqueue(t *testing.T) {
	sc := &fakeScanner{
		files: []*scannerv1.DiscoveredFile{
			mkFile("f1", "Show/S01E01.mkv", []byte(`{"format":{"duration":"120.5"}}`), nil),
			mkFile("f2", "Show/S01E02.mkv", []byte(`{"format":{"duration":"125.0"}}`), nil),
		},
		identify: map[string]*scannerv1.IdentifyResult{
			"f1": mkIdentified("f1", `{"title":"Breaking Bad","season":1,"episode":1}`),
			"f2": mkIdentified("f2", `{"title":"Breaking Bad","season":1,"episode":2}`),
		},
	}

	s, r, libID := setupStore(t)
	rr := &recordingResolver{scanner: sc}
	notify := &recordingNotifier{store: s}
	var enrichCalls int
	enr := forbiddingEnricher(&enrichCalls)

	res, err := runScan(context.Background(), s, r, rr.resolve, enr, notify.notify, libID)
	if err != nil {
		t.Fatalf("runScan: %v", err)
	}
	if res.Persisted != 2 {
		t.Fatalf("Persisted = %d, want 2", res.Persisted)
	}
	// B1/AC-async: scan persisted both items and did NOT enrich inline.
	if enrichCalls != 0 {
		t.Errorf("inline enricher invoked %d times; scan must not enrich inline", enrichCalls)
	}
	// AC-1/AC-async: items persisted pending with the base doc (parsed present).
	items, qerr := s.QueryItems(context.Background(), libID, "", 100, 0)
	if qerr != nil {
		t.Fatalf("QueryItems: %v", qerr)
	}
	if len(items) != 2 {
		t.Fatalf("persisted items = %d, want 2", len(items))
	}
	for _, it := range items {
		if it.Status != "pending" {
			t.Errorf("item %q Status = %q, want pending (worker advances async)", it.FileID, it.Status)
		}
		d := decodeDoc(t, it.Document)
		if d.Parsed == nil {
			t.Errorf("item %q parsed = nil, want present (worker reconstructs base, D-Q2/S7)", it.FileID)
		}
	}
	// S5: Notify fired exactly once, post-drain, for the right library, AFTER
	// both items were persisted (atCount==2 proves the drain completed first).
	calls, atCount := notify.snapshot()
	if len(calls) != 1 {
		t.Fatalf("Notify calls = %d, want 1 (post-drain handoff)", len(calls))
	}
	if calls[0] != libID {
		t.Errorf("Notify libraryID = %d, want %d", calls[0], libID)
	}
	if len(atCount) != 1 || atCount[0] != 2 {
		t.Errorf("Notify atCount = %v, want [2] (called after both items persisted)", atCount)
	}
	// AC-3: scan.Result shape unchanged (only timing changed — items pending).
	if res.LibraryID != libID || res.Discovered != 2 {
		t.Errorf("Result = {Lib:%d Disc:%d}, want {Lib:%d Disc:2}", res.LibraryID, res.Discovered, libID)
	}
	if res.StartedAt.IsZero() || res.FinishedAt.IsZero() {
		t.Errorf("timestamps not set: started=%v finished=%v", res.StartedAt, res.FinishedAt)
	}
}

// TestRunScan_StaleOnRescan is the S2(scan) joint test for AC-states(c): a
// re-scan of a file whose base identity changed advances the item to "stale"
// (minimal B1 basis — compare parsed+ffprobe); an unchanged re-scan preserves
// the prior status so a settled item is not regressed to pending.
func TestRunScan_StaleOnRescan(t *testing.T) {
	file := mkFile("f1", "Show/S01E01.mkv", []byte(`{"format":{"duration":"120.5"}}`), nil)
	identifyA := mkIdentified("f1", `{"title":"Breaking Bad","season":1,"episode":1}`)
	// baseA is exactly what persist's assembleBaseDoc produces for (file, A) —
	// pre-seeding it makes an unchanged re-scan compare byte-equal (no spurious
	// stale), so the only variable between cases is the re-scan's identity. The
	// rootPath is libRoot: scan stamps absolute_path=Join(libRoot, rel) into
	// parsed for all items (D-6), and runScan threads lib.RootPath (== libRoot).
	baseA := assembleBaseDoc(file, identifyA, "tv", 1, libRoot)

	cases := []struct {
		name       string
		priorStat  string
		reidentify *scannerv1.IdentifyResult // nil => replay identifyA (unchanged)
		wantStatus string
	}{
		{
			name:       "changed_parsed_to_stale",
			priorStat:  "pending",
			reidentify: mkIdentified("f1", `{"title":"Better Call Saul","season":1,"episode":1}`),
			wantStatus: "stale",
		},
		{
			name:       "unchanged_preserves_pending",
			priorStat:  "pending",
			reidentify: nil, // replay A -> unchanged -> prior preserved
			wantStatus: "pending",
		},
		{
			// Preserve-prior prevents regression: a ready item re-scanned unchanged
			// is NOT knocked back to pending (would otherwise strand it — the queue
			// only settles enriched items, so a pending-with-all-namespaces item
			// would never re-advance).
			name:       "unchanged_preserves_ready_no_regression",
			priorStat:  "ready",
			reidentify: nil,
			wantStatus: "ready",
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			s, r, libID := setupStore(t)
			ctx := context.Background()
			if err := s.PutItem(ctx, store.Item{
				ID: itemID(libID, "f1"), ModuleID: "tv", LibraryID: libID, FileID: "f1",
				RelativePath: "Show/S01E01.mkv", MediaType: "tv",
				Document: marshalDoc(baseA), SchemaVersion: 1, Status: tc.priorStat,
			}); err != nil {
				t.Fatalf("seed PutItem: %v", err)
			}
			identify := tc.reidentify
			if identify == nil {
				identify = identifyA
			}
			sc := &fakeScanner{
				files:    []*scannerv1.DiscoveredFile{file},
				identify: map[string]*scannerv1.IdentifyResult{"f1": identify},
			}
			rr := &recordingResolver{scanner: sc}
			if _, err := runScan(ctx, s, r, rr.resolve, passthroughEnricher(), nil, libID); err != nil {
				t.Fatalf("runScan: %v", err)
			}
			items, err := s.QueryItems(ctx, libID, "", 100, 0)
			if err != nil {
				t.Fatalf("QueryItems: %v", err)
			}
			if len(items) != 1 {
				t.Fatalf("persisted items = %d, want 1 (upsert by file_id)", len(items))
			}
			if items[0].Status != tc.wantStatus {
				t.Errorf("re-scan status = %q, want %q", items[0].Status, tc.wantStatus)
			}
		})
	}
}
